import type { IiifManifest, ModsRecord, PublicWork } from '../../api/client.js';
import type { SearchFilters } from '../../api/queries.js';

/**
 * Reading a work's IIIF manifest and MODS record for the work page: its pages (canvases), the
 * spreads of a book, the labelled record with links to filtered searches, and the rights.
 */

type LanguageMap = IiifManifest['label'];

/** The values of a IIIF language map, English first, then `none`, then any other language. */
export function mapValues(map: LanguageMap | undefined): string[] {
  if (map === undefined) return [];
  return map['en'] ?? map['none'] ?? Object.values(map)[0] ?? [];
}

/** A language map's first value. */
export function mapText(map: LanguageMap | undefined): string | undefined {
  return mapValues(map)[0];
}

/** A caption track of a stream: a WebVTT file. */
export interface CaptionTrack {
  readonly src: string;
  /** BCP 47 language tag. */
  readonly language: string;
  readonly label: string;
}

/** What a video or audio canvas plays: its HLS stream, running time and caption tracks. */
export interface Media {
  readonly kind: 'video' | 'sound';
  /** The HLS main playlist. */
  readonly src: string;
  readonly durationMs: number;
  readonly captions: readonly CaptionTrack[];
}

/** One canvas of the manifest: a page of a book, one image of a work, or a video or audio file. */
export interface Page {
  /** 0-based position in the manifest. */
  readonly index: number;
  readonly label: string;
  /**
   * The file set behind the canvas's IIIF image service (a video's poster); undefined when it
   * has none (audio).
   */
  readonly fileSetId: string | undefined;
  /** The canvas size in pixels; 0 for audio. */
  readonly width: number;
  readonly height: number;
  /** Set when the canvas plays a stream rather than showing an image. */
  readonly media: Media | undefined;
}

/** The file set of an image service id, `https://host/iiif/3/<fileSetId>`. */
function fileSetOf(serviceId: string | undefined): string | undefined {
  if (serviceId === undefined) return undefined;
  const last = serviceId.replace(/\/+$/, '').split('/').pop();
  return last === undefined || last === '' ? undefined : decodeURIComponent(last);
}

type Canvas = IiifManifest['items'][number];

function mediaOf(canvas: Canvas): Media | undefined {
  const body = canvas.items[0]?.items[0]?.body;
  if (body === undefined || body.type === 'Image') return undefined;
  const captions = (canvas.annotations?.[0]?.items ?? []).map((annotation): CaptionTrack => ({
    src: annotation.body.id,
    language: annotation.body.language,
    label: mapText(annotation.body.label) ?? annotation.body.language,
  }));
  return {
    kind: body.type === 'Video' ? 'video' : 'sound',
    src: body.id,
    durationMs: Math.round(body.duration * 1000),
    captions,
  };
}

export function pagesOf(manifest: IiifManifest): Page[] {
  return manifest.items.map((canvas, index) => {
    const body = canvas.items[0]?.items[0]?.body;
    const media = mediaOf(canvas);
    const image = body?.type === 'Image' ? body : canvas.thumbnail?.[0];
    return {
      index,
      label: mapText(canvas.label) ?? `Page ${String(index + 1)}`,
      fileSetId: fileSetOf(image?.service[0]?.id),
      width: canvas.width ?? 0,
      height: canvas.height ?? 0,
      media,
    };
  });
}

/** A PDF of the work to download (the manifest's `rendering`). */
export interface Pdf {
  readonly label: string;
  readonly href: string;
}

/** The work's PDFs: `PDF`, or `PDF: Volume 1` when there are several. */
export function pdfsOf(manifest: IiifManifest): Pdf[] {
  return (manifest.rendering ?? []).map((rendering) => ({
    label: mapText(rendering.label) ?? 'PDF',
    href: rendering.id,
  }));
}

/** A running time as a clock reads it: `0:05`, `12:34`, `1:02:03`. */
export function clockTime(ms: number): string {
  const total = Math.max(0, Math.round(ms / 1000));
  const hours = Math.floor(total / 3600);
  const minutes = Math.floor((total % 3600) / 60);
  const seconds = String(total % 60).padStart(2, '0');
  return hours > 0
    ? `${String(hours)}:${String(minutes).padStart(2, '0')}:${seconds}`
    : `${String(minutes)}:${seconds}`;
}

/** A book reads as spreads: the cover alone on the right, then facing pairs (2–3, 4–5, ...). */
export function isPaged(manifest: IiifManifest): boolean {
  return manifest.behavior?.includes('paged') ?? false;
}

/** The 0-based page indexes shown together with page `index` in spread mode. */
export function spreadOf(index: number, count: number): number[] {
  if (index <= 0 || count <= 1) return [0];
  const left = index % 2 === 1 ? index : index - 1;
  return left + 1 < count ? [left, left + 1] : [left];
}

/** `?page=` (1-based) as a 0-based index into `count` pages; anything invalid is the first page. */
export function pageFromParam(value: string | null, count: number): number {
  const page = Number(value);
  if (!Number.isInteger(page) || page < 1) return 0;
  return Math.min(page, count) - 1;
}

/** The value of one metadata row; `filter` makes it a link to the matching search. */
export interface MetadataValue {
  readonly text: string;
  readonly filter?: { readonly facet: keyof SearchFilters; readonly value: string };
}

export interface MetadataRow {
  readonly label: string;
  readonly values: readonly MetadataValue[];
}

/** Rows the page shows in their own cards (rights) or links (collections), not in the record. */
const SHOWN_ELSEWHERE = new Set(['Rights', 'Collection']);

/**
 * The facet value behind each value of a linked row, in the manifest's order (the Public API
 * writes the rows from the same MODS fields, ADR 0022): names, genres, topical and geographic
 * subjects and language codes. A row links only when the counts agree.
 */
function facetValues(label: string, mods: ModsRecord) {
  const subjects = mods.subject ?? [];
  switch (label) {
    case 'Name':
      return { facet: 'name', values: (mods.name ?? []).map((name) => name.namePart) } as const;
    case 'Genre':
      return { facet: 'genre', values: (mods.genre ?? []).map((genre) => genre.value) } as const;
    case 'Subject':
      return {
        facet: 'subject',
        values: subjects.filter((s) => s.kind !== 'geographic').map((s) => s.value),
      } as const;
    case 'Place':
      return {
        facet: 'subject',
        values: subjects.filter((s) => s.kind === 'geographic').map((s) => s.value),
      } as const;
    case 'Language':
      return { facet: 'language', values: mods.language ?? [] } as const;
    default:
      return undefined;
  }
}

/** The manifest's labelled record, with names, genres, subjects, places and languages linked. */
export function metadataRows(manifest: IiifManifest, work: PublicWork): MetadataRow[] {
  return manifest.metadata.flatMap((entry) => {
    const label = mapText(entry.label);
    if (label === undefined || SHOWN_ELSEWHERE.has(label)) return [];
    const texts = mapValues(entry.value);
    const linked = facetValues(label, work.mods);
    const values = texts.map((text, index): MetadataValue => {
      const value = linked?.values[index];
      return linked === undefined || value === undefined || linked.values.length !== texts.length
        ? { text }
        : { text, filter: { facet: linked.facet, value } };
    });
    return values.length === 0 ? [] : [{ label, values }];
  });
}

/** `/search?f.subject=Geysers`: the search a record value links to. */
export function filterHref(filter: NonNullable<MetadataValue['filter']>): string {
  return `/search?${new URLSearchParams({ [`f.${filter.facet}`]: filter.value }).toString()}`;
}

/** The roles in a manifest name value, `Baum, L. Frank (Lyman Frank), 1856-1919 (author)`. */
function rolesIn(value: string | undefined, namePart: string): string | undefined {
  if (!value?.startsWith(namePart)) return undefined;
  const match = /^\s*\((.+)\)$/.exec(value.slice(namePart.length));
  return match?.[1];
}

/**
 * A name as a reader says it: a personal name `Baum, L. Frank (Lyman Frank), 1856-1919` becomes
 * `L. Frank Baum`; other names lose only their dates.
 */
export function spokenName(name: { readonly namePart: string; readonly type?: string }): string {
  const parts = withoutDates(name.namePart);
  if (name.type !== 'personal' || parts.length < 2) return parts.join(', ');
  const [family = '', given = ''] = parts;
  return `${given} ${family}`;
}

/** `Baum, L. Frank (Lyman Frank), 1856-1919` → `['Baum', 'L. Frank']`: no dates or fuller forms. */
export function withoutDates(namePart: string): string[] {
  const plain = namePart.replace(/\s*\([^)]*\)/g, '');
  const parts = plain.split(',').map((part) => part.trim());
  const kept = parts.filter((part, index) => index === 0 || !/\d/.test(part));
  return kept.filter((part) => part !== '');
}

/** The byline's people: `L. Frank Baum, author`, from the record and the manifest's role labels. */
export function bylineNames(manifest: IiifManifest, work: PublicWork): string[] {
  const row = manifest.metadata.find((entry) => mapText(entry.label) === 'Name');
  const labelled = mapValues(row?.value);
  return (work.mods.name ?? []).map((name, index) => {
    const roles = rolesIn(labelled[index], name.namePart);
    const spoken = spokenName(name);
    return roles === undefined ? spoken : `${spoken}, ${roles}`;
  });
}

/** The work's date as catalogued (EDTF): created, else issued. */
export function catalogDate(mods: ModsRecord): string | undefined {
  return mods.originInfo?.dateCreated ?? mods.originInfo?.dateIssued;
}

export interface Rights {
  /** `No Copyright - United States`, from the manifest's labelled record. */
  readonly name: string | undefined;
  /** The required statement: what may be done with the item. */
  readonly statement: string | undefined;
  /** The rights statement or licence, as an `https` address. */
  readonly href: string | undefined;
}

export function rightsOf(manifest: IiifManifest): Rights {
  const row = manifest.metadata.find((entry) => mapText(entry.label) === 'Rights');
  return {
    name: mapText(row?.value),
    statement: mapValues(manifest.requiredStatement?.value).join(' ') || undefined,
    href: manifest.rights?.replace(/^http:/, 'https:'),
  };
}

/** One page at a time, or a book's facing pages. */
export type ReaderMode = 'page' | 'spread';

/** The 0-based pages on the stage when the reader is at page `index`. */
export function visiblePages(index: number, count: number, mode: ReaderMode): number[] {
  return mode === 'spread' ? spreadOf(index, count) : [index];
}

/** The page to go to for the previous (`-1`) or next (`1`) page or spread, if there is one. */
export function turnTo(
  index: number,
  count: number,
  mode: ReaderMode,
  step: -1 | 1,
): number | undefined {
  const visible = visiblePages(index, count, mode);
  const target = step === 1 ? (visible.at(-1) ?? index) + 1 : (visible[0] ?? index) - 1;
  if (target < 0 || target >= count) return undefined;
  return visiblePages(target, count, mode)[0];
}
