import type { ModsRecord, PublicWork } from '../../api/client.js';
import { withoutDates } from './manifest.js';

/**
 * Citations built in the browser from the work's MODS record: APA (7th), MLA (9th), Chicago
 * (17th, bibliography), BibTeX and RIS. They follow each style's pattern for the fields a
 * catalog record has; readers are told to check them against their style guide.
 */

/** A run of citation text; titles are italic in the prose styles. */
export interface Segment {
  readonly text: string;
  readonly italic?: boolean;
}

export type CitationStyle = 'apa' | 'mla' | 'chicago' | 'bibtex';

export const CITATION_STYLES: readonly { readonly id: CitationStyle; readonly label: string }[] = [
  { id: 'apa', label: 'APA' },
  { id: 'mla', label: 'MLA' },
  { id: 'chicago', label: 'Chicago' },
  { id: 'bibtex', label: 'BibTeX' },
];

export interface CitationSource {
  readonly work: PublicWork;
  /** The work page's address. */
  readonly url: string;
  /** The library's name (`theme.json`), as the site or database. */
  readonly siteName: string;
  readonly accessed: Date;
}

/**
 * MARC relators that make a name the work's creator; names without a role count too. A work
 * with only an illustrator is cited under the illustrator.
 */
const CREATOR_ROLES = new Set(['aut', 'cre', 'art', 'pht', 'dsn', 'ctg', 'cmp', 'lyr', 'prf']);

/** Contributors after the title: `(W. W. Denslow, Illus.)` in APA, `Illustrated by` elsewhere. */
const CONTRIBUTOR_ROLES = {
  ill: { apa: 'Illus.', by: 'Illustrated by' },
  edt: { apa: 'Ed.', by: 'Edited by' },
  trl: { apa: 'Trans.', by: 'Translated by' },
} as const;

type ContributorRole = keyof typeof CONTRIBUTOR_ROLES;

interface Person {
  /** `Baum` (personal) or the whole corporate name. */
  readonly family: string;
  /** `L. Frank`; undefined for corporate names. */
  readonly given: string | undefined;
}

type ModsName = NonNullable<ModsRecord['name']>[number];

function personOf(name: ModsName): Person {
  const parts = withoutDates(name.namePart);
  if (name.type !== 'personal' || parts.length < 2)
    return { family: parts.join(', '), given: undefined };
  return { family: parts[0] ?? '', given: parts[1] };
}

function isContributor(name: ModsName): ContributorRole | undefined {
  const roles = name.role ?? [];
  if (roles.some((role) => CREATOR_ROLES.has(role))) return undefined;
  return roles.find((role): role is ContributorRole => role in CONTRIBUTOR_ROLES);
}

/** The work's creators: authors, artists, photographers... (an illustrator only without them). */
function creatorsOf(mods: ModsRecord): Person[] {
  const names = mods.name ?? [];
  const primary = names.filter(
    (name) =>
      (name.role ?? []).length === 0 || (name.role ?? []).some((role) => CREATOR_ROLES.has(role)),
  );
  return (primary.length > 0 ? primary : names.filter((name) => isContributor(name) === 'ill')).map(
    personOf,
  );
}

/** The contributors after the title (illustrators, editors, translators). */
function contributorsOf(mods: ModsRecord): { person: Person; role: ContributorRole }[] {
  const creators = creatorsOf(mods);
  return (mods.name ?? []).flatMap((name) => {
    const role = isContributor(name);
    const person = personOf(name);
    if (role === undefined || creators.some((c) => c.family === person.family)) return [];
    return [{ person, role }];
  });
}

const initials = (given: string) =>
  given
    .split(/\s+/)
    .filter((part) => part !== '')
    .map((part) => `${part.replace(/\.$/, '').charAt(0)}.`)
    .join(' ');

const natural = (person: Person) =>
  person.given === undefined ? person.family : `${person.given} ${person.family}`;
const inverted = (person: Person) =>
  person.given === undefined ? person.family : `${person.family}, ${person.given}`;

/** `A`, `A and B`, `A, B, and C` (`&` in APA). */
function list(items: readonly string[], and: string): string {
  if (items.length <= 1) return items.join('');
  if (items.length === 2)
    return `${items[0] ?? ''}${and === '&' ? ', & ' : ` ${and} `}${items[1] ?? ''}`;
  return `${items.slice(0, -1).join(', ')}, ${and} ${items.at(-1) ?? ''}`;
}

const endWith = (text: string, mark: string) => (/[.?!]$/.test(text) ? text : `${text}${mark}`);

function titleOf(work: PublicWork): string {
  const primary = work.mods.titleInfo.find((title) => title.type === undefined);
  if (primary === undefined) return work.title ?? 'Untitled';
  const main = [primary.nonSort, primary.title].filter((part) => part !== undefined).join(' ');
  return primary.subTitle === undefined ? main : `${main}: ${primary.subTitle}`;
}

interface CitationDate {
  /** `1900`, `1898–1905`; undefined when the record has no date. */
  readonly year: string | undefined;
  readonly approximate: boolean;
}

/** The catalogued date (EDTF) as a citation year: `1938~` is approximate, `1898/1905` a range. */
function dateOf(mods: ModsRecord): CitationDate {
  const edtf = mods.originInfo?.dateIssued ?? mods.originInfo?.dateCreated;
  if (edtf === undefined) return { year: undefined, approximate: false };
  const years = [...edtf.matchAll(/\d{4}|\d{3}X|\d{2}XX/g)].map((match) =>
    match[0].replace(/X/g, '0'),
  );
  const unique = [...new Set(years)];
  return {
    year: unique.length === 0 ? undefined : unique.join('–'),
    approximate: /[~%?X]/.test(edtf),
  };
}

/** APA's bracketed description of a non-text work. */
const APA_TYPE: Readonly<Record<string, string>> = {
  'still image': 'Image',
  cartographic: 'Map',
  'notated music': 'Musical score',
  'sound recording': 'Audio recording',
  'sound recording-musical': 'Audio recording',
  'sound recording-nonmusical': 'Audio recording',
  'moving image': 'Video',
  'three dimensional object': 'Object',
  'mixed material': 'Archival material',
};

function publisherOf(mods: ModsRecord, creators: readonly Person[]): string | undefined {
  const publisher = mods.originInfo?.publisher?.[0];
  // APA and MLA leave out a publisher that is also the author.
  return creators.some((creator) => creator.family === publisher) ? undefined : publisher;
}

const longDate = (date: Date) =>
  date.toLocaleDateString('en-US', {
    year: 'numeric',
    month: 'long',
    day: 'numeric',
  });

/** `2026-10-10`, in the reader's time zone (the day they looked). */
const isoDay = (date: Date) =>
  [date.getFullYear(), date.getMonth() + 1, date.getDate()]
    .map((part, index) => String(part).padStart(index === 0 ? 4 : 2, '0'))
    .join('-');

const MLA_MONTHS = [
  'Jan.',
  'Feb.',
  'Mar.',
  'Apr.',
  'May',
  'June',
  'July',
  'Aug.',
  'Sept.',
  'Oct.',
  'Nov.',
  'Dec.',
];

const mlaDate = (date: Date) =>
  `${String(date.getDate())} ${MLA_MONTHS[date.getMonth()] ?? ''} ${String(date.getFullYear())}`;

export function apa({ work, url, siteName }: CitationSource): Segment[] {
  const { mods } = work;
  const creators = creatorsOf(mods);
  const date = dateOf(mods);
  const year = date.year === undefined ? 'n.d.' : `${date.approximate ? 'ca. ' : ''}${date.year}`;
  const authors = list(
    creators.map((person) =>
      person.given === undefined ? person.family : `${person.family}, ${initials(person.given)}`,
    ),
    '&',
  );
  const title = titleOf(work);
  const contributors = contributorsOf(mods).map(
    ({ person, role }) => `${natural(person)}, ${CONTRIBUTOR_ROLES[role].apa}`,
  );
  const type = APA_TYPE[mods.typeOfResource?.[0] ?? ''];
  const described = [
    contributors.length > 0 ? ` (${contributors.join('; ')})` : '',
    type === undefined ? '' : ` [${type}]`,
  ].join('');
  const publisher = publisherOf(mods, creators);
  const source = `${publisher === undefined ? '' : `${endWith(publisher, '.')} `}${endWith(siteName, '.')} ${url}`;
  const titleEnd = described === '' && /[.?!]$/.test(title) ? '' : '.';
  if (creators.length === 0) {
    return [
      { text: title, italic: true },
      { text: `${described}${titleEnd} (${year}). ${source}` },
    ];
  }
  return [
    { text: `${endWith(authors, '.')} (${year}). ` },
    { text: title, italic: true },
    { text: `${described}${titleEnd} ${source}` },
  ];
}

export function mla({ work, url, siteName, accessed }: CitationSource): Segment[] {
  const { mods } = work;
  const creators = creatorsOf(mods);
  const first = creators[0];
  let authors: string | undefined;
  if (first !== undefined) {
    if (creators.length === 1) authors = inverted(first);
    else if (creators.length === 2)
      authors = `${inverted(first)}, and ${natural(creators[1] ?? first)}`;
    else authors = `${inverted(first)}, et al`;
  }
  const date = dateOf(mods);
  const contributors = contributorsOf(mods).map(
    ({ person, role }) => `${CONTRIBUTOR_ROLES[role].by} ${natural(person)}`,
  );
  const publisher = publisherOf(mods, creators);
  const facts = [
    ...contributors,
    publisher,
    date.year === undefined ? undefined : `${date.approximate ? 'circa ' : ''}${date.year}`,
  ].filter((part) => part !== undefined);
  return [
    ...(authors === undefined ? [] : [{ text: `${endWith(authors, '.')} ` }]),
    { text: titleOf(work), italic: true },
    { text: `. ${facts.length > 0 ? `${endWith(facts.join(', '), '.')} ` : ''}` },
    { text: siteName, italic: true },
    { text: `, ${url}. Accessed ${mlaDate(accessed)}.` },
  ];
}

export function chicago({ work, url, siteName }: CitationSource): Segment[] {
  const { mods } = work;
  const creators = creatorsOf(mods);
  const authors = creators.map((person, index) =>
    index === 0 ? inverted(person) : natural(person),
  );
  const date = dateOf(mods);
  const contributors = contributorsOf(mods).map(
    ({ person, role }) => `${CONTRIBUTOR_ROLES[role].by} ${natural(person)}.`,
  );
  const place = mods.originInfo?.place?.[0];
  const publisher = mods.originInfo?.publisher?.[0];
  const year = date.year === undefined ? 'n.d.' : `${date.approximate ? 'ca. ' : ''}${date.year}`;
  const imprint = [
    place === undefined || publisher === undefined ? publisher : `${place}: ${publisher}`,
    year,
  ]
    .filter((part) => part !== undefined)
    .join(', ');
  return [
    ...(authors.length === 0 ? [] : [{ text: `${endWith(list(authors, 'and'), '.')} ` }]),
    { text: titleOf(work), italic: true },
    {
      text: `. ${contributors.length > 0 ? `${contributors.join(' ')} ` : ''}${endWith(imprint, '.')} ${endWith(siteName, '.')} ${url}.`,
    },
  ];
}

const isBook = (mods: ModsRecord, work: PublicWork) =>
  (mods.typeOfResource ?? []).includes('text') && work.behavior === 'paged';

/** A BibTeX value: no braces or backslashes (they would end the field), LaTeX specials escaped. */
const bib = (value: string) => value.replace(/[{}\\]/g, '').replace(/[&%$#_]/g, '\\$&');

/** `baum1900wonderful`: the first creator, the year and the title's first long word. */
function citeKey(work: PublicWork): string {
  const ascii = (text: string) =>
    text
      .normalize('NFKD')
      .replace(/[^\w\s]/g, '')
      .toLowerCase();
  const creator = ascii(creatorsOf(work.mods)[0]?.family.split(/\s+/)[0] ?? 'cdl');
  const word = ascii(titleOf(work))
    .split(/\s+/)
    .find((part) => part.length > 3);
  return `${creator}${dateOf(work.mods).year?.slice(0, 4) ?? ''}${word ?? ''}`;
}

export function bibtex({ work, url, siteName, accessed }: CitationSource): string {
  const { mods } = work;
  const contributors = contributorsOf(mods);
  const fields: [string, string | undefined][] = [
    [
      'author',
      creatorsOf(mods)
        .map((person) => bib(inverted(person)))
        .join(' and ') || undefined,
    ],
    ['title', `{${bib(titleOf(work))}}`],
    ['year', dateOf(mods).year],
    ['publisher', mods.originInfo?.publisher?.[0]],
    ['address', mods.originInfo?.place?.[0]],
    [
      'note',
      contributors.length === 0
        ? undefined
        : contributors
            .map(({ person, role }) => `${CONTRIBUTOR_ROLES[role].by} ${natural(person)}`)
            .join('; '),
    ],
    ['howpublished', bib(siteName)],
    ['url', url],
    ['urldate', isoDay(accessed)],
  ];
  const body = fields
    .filter((field): field is [string, string] => field[1] !== undefined)
    .map(
      ([name, value]) => `  ${name} = {${name === 'title' || name === 'url' ? value : bib(value)}}`,
    )
    .join(',\n');
  return `@${isBook(mods, work) ? 'book' : 'misc'}{${citeKey(work)},\n${body}\n}`;
}

const RIS_TYPE: Readonly<Record<string, string>> = {
  text: 'BOOK',
  'still image': 'ART',
  cartographic: 'MAP',
  'notated music': 'MUSIC',
  'sound recording': 'SOUND',
  'sound recording-musical': 'SOUND',
  'sound recording-nonmusical': 'SOUND',
  'moving image': 'VIDEO',
};

/** RIS for reference managers (Zotero, EndNote, Mendeley); lines end in CRLF as the format asks. */
export function ris({ work, url, siteName, accessed }: CitationSource): string {
  const { mods } = work;
  const date = dateOf(mods);
  const lines: [string, string | undefined][] = [
    ['TY', RIS_TYPE[mods.typeOfResource?.[0] ?? ''] ?? 'GEN'],
    ...creatorsOf(mods).map((person): [string, string] => ['AU', inverted(person)]),
    ...contributorsOf(mods).map(({ person }): [string, string] => ['A2', inverted(person)]),
    ['TI', titleOf(work)],
    ['PY', date.year?.slice(0, 4)],
    ['PB', mods.originInfo?.publisher?.[0]],
    ['CY', mods.originInfo?.place?.[0]],
    ['AB', mods.abstract?.[0]],
    ['DB', siteName],
    ['UR', url],
    ['Y2', isoDay(accessed)],
    ['ER', ''],
  ];
  return lines
    .filter((line): line is [string, string] => line[1] !== undefined)
    .map(([tag, value]) => `${tag}  - ${value}`.trimEnd())
    .join('\r\n')
    .concat('\r\n');
}

export function citation(style: CitationStyle, source: CitationSource): Segment[] {
  switch (style) {
    case 'apa':
      return apa(source);
    case 'mla':
      return mla(source);
    case 'chicago':
      return chicago(source);
    case 'bibtex':
      return [{ text: bibtex(source) }];
  }
}

export const plainCitation = (segments: readonly Segment[]) =>
  segments.map((segment) => segment.text).join('');

/** `Accessed October 10, 2026.` under the citation. */
export const accessedLine = (date: Date) => `Accessed ${longDate(date)}.`;
