/**
 * The work page's actions, all built in the browser: Download (IIIF Image API sizes of the page
 * on the stage, the caption files of a video or audio, the work's PDFs and the manifest), Share
 * (the page's address; the system share sheet on phones), Cite (five formats from the MODS
 * record) and IIIF (the manifest in other viewers).
 */

/** IIIF viewers that open any manifest from a URL (`iiif-content`, the IIIF Content State API). */
export const IIIF_VIEWERS: readonly {
  readonly name: string;
  readonly href: (m: string) => string;
}[] = [
  {
    name: 'Mirador',
    href: (manifest) =>
      `https://projectmirador.org/embed/?iiif-content=${encodeURIComponent(manifest)}`,
  },
  {
    name: 'Theseus',
    href: (manifest) => `https://theseusviewer.org/?iiif-content=${encodeURIComponent(manifest)}`,
  },
  {
    name: 'Clover',
    href: (manifest) =>
      `https://samvera-labs.github.io/clover-iiif/docs/viewer/demo?iiif-content=${encodeURIComponent(manifest)}`,
  },
];

export const WHAT_IS_IIIF = 'https://iiif.io/get-started/';

/** Copies `text` and says so in a toast. */
export async function copyText(text: string, what: string): Promise<void> {
  try {
    await navigator.clipboard.writeText(text);
    toast.success(`${what} copied`);
  } catch {
    toast.error(`Could not copy the ${what.toLowerCase()}; select it and copy it instead.`);
  }
}

/**
 * The actions' buttons: a row of outline buttons, and on phones four equal tiles with the icon
 * over the label.
 */
const ACTION =
  'max-sm:h-auto max-sm:flex-col max-sm:gap-1 max-sm:px-1 max-sm:py-2 max-sm:text-xs max-sm:[&_svg:not([class*=size-])]:size-4.5';

const integer = new Intl.NumberFormat('en-US');

/** The download sizes of a page: small and large JPEGs when the image is bigger, and full size. */
export function downloadSizes(
  page: Page,
  urls: { readonly image: (size: number) => string; readonly full: string },
) {
  const longest = Math.max(page.width, page.height);
  const scaled = [
    { label: 'Small JPEG', size: 800 },
    { label: 'Large JPEG', size: 2000 },
  ].filter((option) => option.size < longest);
  return [
    ...scaled.map((option) => ({
      label: option.label,
      hint: `${integer.format(option.size)} px`,
      href: urls.image(option.size),
    })),
    {
      label: 'Full size JPEG',
      hint: `${integer.format(page.width)} × ${integer.format(page.height)}`,
      href: urls.full,
    },
  ];
}

function DownloadMenu({
  page,
  pdfs,
  manifestUrl,
}: {
  readonly page: Page | undefined;
  readonly pdfs: readonly Pdf[];
  readonly manifestUrl: string;
}) {
  const iiif = useIiif();
  const fileSetId = page?.fileSetId;
  const captions = page?.media?.captions ?? [];
  const sizes =
    page === undefined || fileSetId === undefined || page.media !== undefined
      ? []
      : downloadSizes(page, {
          image: (size) => iiif.image(fileSetId, size),
          full: iiif.info(fileSetId).replace(/\/info\.json$/, '/full/max/0/default.jpg'),
        });
  return (
    <DropdownMenu>
      <DropdownMenuTrigger render={<Button variant="outline" className={ACTION} />}>
        <DownloadIcon aria-hidden="true" />
        Download
        <ChevronDownIcon aria-hidden="true" className="max-sm:hidden" />
      </DropdownMenuTrigger>
      <DropdownMenuContent className="w-72">
        {page !== undefined && sizes.length > 0 && (
          <>
            <DropdownMenuGroup>
              <DropdownMenuLabel>{`This page (${page.label})`}</DropdownMenuLabel>
              {sizes.map((size) => (
                <DropdownMenuItem
                  key={size.label}
                  render={<a href={size.href} download target="_blank" rel="noreferrer" />}
                >
                  <ImageIcon aria-hidden="true" />
                  <span className="flex-1">{size.label}</span>
                  <span className="text-xs text-muted-foreground tabular-nums">{size.hint}</span>
                </DropdownMenuItem>
              ))}
            </DropdownMenuGroup>
            <DropdownMenuSeparator />
          </>
        )}
        {page !== undefined && captions.length > 0 && (
          <>
            <DropdownMenuGroup>
              <DropdownMenuLabel>{`Captions (${page.label})`}</DropdownMenuLabel>
              {captions.map((track) => (
                <DropdownMenuItem
                  key={track.src}
                  render={<a href={track.src} download target="_blank" rel="noreferrer" />}
                >
                  <CaptionsIcon aria-hidden="true" />
                  <span className="flex-1">{track.label}</span>
                  <span className="text-xs text-muted-foreground">WebVTT</span>
                </DropdownMenuItem>
              ))}
            </DropdownMenuGroup>
            <DropdownMenuSeparator />
          </>
        )}
        <DropdownMenuGroup>
          <DropdownMenuLabel>Whole item</DropdownMenuLabel>
          {pdfs.map((pdf) => (
            <DropdownMenuItem key={pdf.href} render={<a href={pdf.href} download />}>
              <FileTextIcon aria-hidden="true" />
              {pdf.label}
            </DropdownMenuItem>
          ))}
          <DropdownMenuItem render={<a href={manifestUrl} target="_blank" rel="noreferrer" />}>
            <BracesIcon aria-hidden="true" />
            IIIF manifest (JSON)
          </DropdownMenuItem>
        </DropdownMenuGroup>
      </DropdownMenuContent>
    </DropdownMenu>
  );
}

/** Phones (a coarse pointer and the Web Share API) get the system share sheet. */
function systemShare(): boolean {
  return typeof navigator.share === 'function' && window.matchMedia('(pointer: coarse)').matches;
}

function SharePopover({
  title,
  workUrl,
  page,
}: {
  readonly title: string;
  readonly workUrl: string;
  /** The page on the stage, when the work has several. */
  readonly page: { readonly number: number; readonly label: string } | undefined;
}) {
  const [open, setOpen] = useState(false);
  const [toPage, setToPage] = useState(true);
  const checkboxId = useId();
  const url =
    page !== undefined && toPage && page.number > 1
      ? `${workUrl}?page=${String(page.number)}`
      : workUrl;
  return (
    <Popover
      open={open}
      onOpenChange={(next) => {
        if (next && systemShare()) {
          navigator.share({ title, url }).catch(() => undefined);
          return;
        }
        setOpen(next);
      }}
    >
      <PopoverTrigger render={<Button variant="outline" className={ACTION} />}>
        <Share2Icon aria-hidden="true" />
        Share
      </PopoverTrigger>
      <PopoverContent align="start" className="w-80 gap-3 p-4">
        <PopoverTitle className="font-heading text-base font-semibold">
          Share this item
        </PopoverTitle>
        <input
          readOnly
          aria-label="Link to this item"
          value={url}
          onFocus={(event) => {
            event.currentTarget.select();
          }}
          className="h-8 w-full truncate rounded-md border border-input bg-secondary px-2.5 font-mono text-[11px] text-muted-foreground outline-none focus-visible:ring-3 focus-visible:ring-ring/50"
        />
        <div className="grid grid-cols-2 gap-2">
          <Button
            size="sm"
            onClick={() => {
              void copyText(url, 'Link');
            }}
          >
            <CopyIcon aria-hidden="true" />
            Copy link
          </Button>
          <a
            href={`mailto:?subject=${encodeURIComponent(title)}&body=${encodeURIComponent(url)}`}
            className={cn(
              'inline-flex h-8 items-center justify-center gap-1.5 rounded-md border border-input bg-card px-3 text-[13px] font-medium shadow-xs hover:bg-secondary focus-visible:ring-3 focus-visible:ring-ring/50 focus-visible:outline-none [&_svg]:size-3.5',
            )}
          >
            <MailIcon aria-hidden="true" />
            Email
          </a>
        </div>
        {page !== undefined && page.number > 1 && (
          <label
            htmlFor={checkboxId}
            className="flex items-center gap-2 text-[13px] text-muted-foreground"
          >
            <input
              id={checkboxId}
              type="checkbox"
              checked={toPage}
              onChange={(event) => {
                setToPage(event.currentTarget.checked);
              }}
              className="size-4 accent-primary"
            />
            {`Link to page ${String(page.number)} (${page.label})`}
          </label>
        )}
        <p className="text-xs text-muted-foreground">
          On phones the system share sheet opens instead.
        </p>
      </PopoverContent>
    </Popover>
  );
}

function Citation({ segments }: { readonly segments: readonly Segment[] }) {
  return segments.map((segment, index) =>
    segment.italic === true ? (
      <i key={index}>{segment.text}</i>
    ) : (
      <span key={index}>{segment.text}</span>
    ),
  );
}

/** Saves `text` as a file the browser downloads (`cite.ris`). */
function saveFile(name: string, text: string, type: string) {
  const url = URL.createObjectURL(new Blob([text], { type }));
  const anchor = document.createElement('a');
  anchor.href = url;
  anchor.download = name;
  anchor.click();
  URL.revokeObjectURL(url);
}

function CiteDialog({
  work,
  workUrl,
  rights,
}: {
  readonly work: PublicWork;
  readonly workUrl: string;
  readonly rights: string | undefined;
}) {
  const brand = useBrand();
  const [open, setOpen] = useState(false);
  const [style, setStyle] = useState<CitationStyle>('apa');
  const [accessed, setAccessed] = useState(() => new Date());
  const source: CitationSource = { work, url: workUrl, siteName: brand.name, accessed };
  return (
    <>
      <Button
        variant="outline"
        className={ACTION}
        onClick={() => {
          setAccessed(new Date());
          setOpen(true);
        }}
      >
        <QuoteIcon aria-hidden="true" />
        Cite
      </Button>
      <Dialog open={open} onOpenChange={setOpen}>
        <DialogContent className="gap-4 p-6 sm:max-w-xl">
          <DialogHeader>
            <DialogTitle className="font-heading text-xl font-semibold">Cite this item</DialogTitle>
            <DialogDescription>
              Built from the catalog record; check it against your style guide.
            </DialogDescription>
          </DialogHeader>
          <Tabs
            value={style}
            onValueChange={(value: CitationStyle) => {
              setStyle(value);
            }}
          >
            <TabsList variant="line">
              {CITATION_STYLES.map((option) => (
                <TabsTrigger key={option.id} value={option.id} className="px-3">
                  {option.label}
                </TabsTrigger>
              ))}
            </TabsList>
            {CITATION_STYLES.map((option) => (
              <TabsContent key={option.id} value={option.id} className="mt-2">
                {option.id === 'bibtex' ? (
                  <pre className="overflow-x-auto rounded-lg border border-border bg-secondary/60 p-4 font-mono text-xs leading-relaxed">
                    {plainCitation(citation('bibtex', source))}
                  </pre>
                ) : (
                  <p className="rounded-lg border border-border bg-secondary/60 p-4 font-heading text-[15px] leading-relaxed break-words">
                    <Citation segments={citation(option.id, source)} />
                  </p>
                )}
              </TabsContent>
            ))}
          </Tabs>
          <p className="text-[13px] text-muted-foreground">
            {accessedLine(accessed)}
            {rights !== undefined && ` Rights: ${rights}.`}
          </p>
          <DialogFooter className="gap-2">
            <Button
              variant="outline"
              onClick={() => {
                saveFile(
                  `${work.accessionNumber}.ris`,
                  ris(source),
                  'application/x-research-info-systems',
                );
              }}
            >
              <DownloadIcon aria-hidden="true" />
              Download RIS
            </Button>
            <Button
              onClick={() => {
                void copyText(plainCitation(citation(style, source)), 'Citation');
              }}
            >
              <CopyIcon aria-hidden="true" />
              Copy citation
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </>
  );
}

function IiifMenu({ manifestUrl }: { readonly manifestUrl: string }) {
  return (
    <DropdownMenu>
      <DropdownMenuTrigger render={<Button variant="outline" className={ACTION} />}>
        <IiifMark />
        IIIF
        <ChevronDownIcon aria-hidden="true" className="max-sm:hidden" />
      </DropdownMenuTrigger>
      <DropdownMenuContent className="w-64">
        <DropdownMenuItem
          onClick={() => {
            void copyText(manifestUrl, 'Manifest URL');
          }}
        >
          <CopyIcon aria-hidden="true" />
          Copy manifest URL
        </DropdownMenuItem>
        {IIIF_VIEWERS.map((viewer) => (
          <DropdownMenuItem
            key={viewer.name}
            render={<a href={viewer.href(manifestUrl)} target="_blank" rel="noreferrer" />}
          >
            <ExternalLinkIcon aria-hidden="true" />
            {`Open in ${viewer.name}`}
          </DropdownMenuItem>
        ))}
        <DropdownMenuSeparator />
        <DropdownMenuItem render={<a href={WHAT_IS_IIIF} target="_blank" rel="noreferrer" />}>
          <InfoIcon aria-hidden="true" />
          What is IIIF?
        </DropdownMenuItem>
      </DropdownMenuContent>
    </DropdownMenu>
  );
}

/** The IIIF mark: three bars and a slash, drawn in the current colour. */
export function IiifMark({ className }: { readonly className?: string }) {
  return (
    <svg
      aria-hidden="true"
      viewBox="0 0 16 16"
      fill="currentColor"
      className={cn('size-4', className)}
    >
      <rect x="1" y="3" width="2" height="10" rx="0.5" />
      <rect x="5" y="3" width="2" height="10" rx="0.5" />
      <rect x="9" y="3" width="2" height="10" rx="0.5" />
      <path d="M12.6 3h1.9L15 3.5 13.4 13h-1.9l-.5-.5z" />
    </svg>
  );
}

export function WorkActions({
  work,
  page,
  pageCount,
  pdfs = [],
  manifestUrl,
  workUrl,
  rights,
}: {
  readonly work: PublicWork;
  /** The page on the stage. */
  readonly page: Page | undefined;
  readonly pageCount: number;
  /** The work's PDFs (document works). */
  readonly pdfs?: readonly Pdf[];
  readonly manifestUrl: string;
  /** The work page's address, without `?page=`. */
  readonly workUrl: string;
  readonly rights: string | undefined;
}): ReactNode {
  return (
    <div role="group" aria-label="Actions" className="grid grid-cols-4 gap-2 sm:flex sm:flex-wrap">
      <DownloadMenu page={page} pdfs={pdfs} manifestUrl={manifestUrl} />
      <SharePopover
        title={workTitle(work)}
        workUrl={workUrl}
        page={
          page !== undefined && pageCount > 1
            ? { number: page.index + 1, label: page.label }
            : undefined
        }
      />
      <CiteDialog work={work} workUrl={workUrl} rights={rights} />
      <IiifMenu manifestUrl={manifestUrl} />
    </div>
  );
}

/** A copy button for a value shown next to it (the manifest URL). */
export function CopyButton({ text, what }: { readonly text: string; readonly what: string }) {
  const [copied, setCopied] = useState(false);
  return (
    <Button
      variant="ghost"
      size="icon-xs"
      aria-label={`Copy ${what.toLowerCase()}`}
      onClick={() => {
        void copyText(text, what).then(() => {
          setCopied(true);
          setTimeout(() => {
            setCopied(false);
          }, 1500);
        });
      }}
    >
      {copied ? <CheckIcon aria-hidden="true" /> : <CopyIcon aria-hidden="true" />}
    </Button>
  );
}
