import {
  AudioLinesIcon,
  ChevronLeftIcon,
  ChevronRightIcon,
  Columns2Icon,
  ExpandIcon,
  ImageOffIcon,
  LoaderCircleIcon,
  MaximizeIcon,
  RectangleVerticalIcon,
  RotateCwIcon,
  ShrinkIcon,
  ZoomInIcon,
  ZoomOutIcon,
} from 'lucide-react';
import {
  lazy,
  Suspense,
  useEffect,
  useId,
  useRef,
  useState,
  type KeyboardEvent,
  type ReactNode,
  type RefObject,
} from 'react';
import { useIiif } from '../../api/iiif.js';
import { IiifImage } from '../../components/IiifImage.js';
import type { StageImage, ZoomControls } from './DeepZoom.js';
import { clockTime, turnTo, visiblePages, type Page, type ReaderMode } from './manifest.js';
import { Button } from '@/components/ui/button';
import { cn } from '@/lib/utils';

/** OpenSeadragon (about 86 KB gzipped) loads with the first work page, not with the site. */
const DeepZoom = lazy(() => import('./DeepZoom.js'));
/** The player (and hls.js, when the browser needs it) loads with the first video or audio. */
const MediaStage = lazy(() => import('./MediaStage.js'));

const TOOL =
  'text-viewer-foreground hover:bg-viewer-foreground/10 hover:text-viewer-foreground aria-pressed:bg-viewer-foreground/20 dark:hover:bg-viewer-foreground/10';

/** What one canvas of the work is called: a book's page, an image, or an item (video, audio). */
export function nounOf(pages: readonly Page[], paged: boolean): 'page' | 'image' | 'item' {
  if (paged) return 'page';
  return pages.some((page) => page.media !== undefined) ? 'item' : 'image';
}

const capitalized = (noun: string) => `${noun.charAt(0).toUpperCase()}${noun.slice(1)}`;

/** What the stage's toolbar says: the title, or where the reader is in a multi-page work. */
export function pageLabel(
  pages: readonly Page[],
  visible: readonly number[],
  paged: boolean,
): string | undefined {
  if (pages.length <= 1) return undefined;
  const labels = visible.map((index) => pages[index]?.label ?? '').join(', ');
  const first = (visible[0] ?? 0) + 1;
  const last = (visible.at(-1) ?? 0) + 1;
  const count = String(pages.length);
  if (first !== last) return `Pages ${String(first)}–${String(last)} of ${count} · ${labels}`;
  return `${capitalized(nounOf(pages, paged))} ${String(first)} of ${count} · ${labels}`;
}

/** The Fullscreen API where the browser has it (not on iPhones), else the frame fills the window. */
function useFullscreen(frame: RefObject<HTMLElement | null>) {
  const [fallback, setFallback] = useState(false);
  const [native, setNative] = useState(false);
  useEffect(() => {
    const update = () => {
      setNative(
        document.fullscreenElement !== null && document.fullscreenElement === frame.current,
      );
    };
    document.addEventListener('fullscreenchange', update);
    return () => {
      document.removeEventListener('fullscreenchange', update);
    };
  }, [frame]);
  useEffect(() => {
    if (!fallback) return undefined;
    const close = (event: globalThis.KeyboardEvent) => {
      if (event.key === 'Escape') setFallback(false);
    };
    document.addEventListener('keydown', close);
    return () => {
      document.removeEventListener('keydown', close);
    };
  }, [fallback]);
  const toggle = () => {
    if (native) {
      void document.exitFullscreen();
    } else if (document.fullscreenEnabled && frame.current !== null) {
      void frame.current.requestFullscreen();
    } else {
      setFallback((value) => !value);
    }
  };
  return { full: native || fallback, fallback, toggle };
}

/**
 * The work page's reader in the Reading Room's dark viewer frame: the deep-zoom stage, a toolbar
 * with page turns, the page/spread switch for books, labelled zoom, fit, rotate and full-screen
 * buttons and the zoom level, and a strip of page thumbnails. The stage is one tab stop with its
 * own keys (`KEYS_HINT`); OpenSeadragon's navigator mini-map sits in its corner. A video or
 * audio canvas plays on the stage instead (`MediaStage`), alone and without the zoom buttons.
 */
export function Reader({
  title,
  pages,
  paged,
  current,
  mode,
  onMode,
  onTurn,
}: {
  /** The work's title: the stage's name, and the toolbar's text for a single image. */
  readonly title: string;
  readonly pages: readonly Page[];
  /** A book (`behavior: paged`): pages, spreads and the page/spread switch. */
  readonly paged: boolean;
  /** The 0-based page shown (the first of a spread). */
  readonly current: number;
  readonly mode: ReaderMode;
  readonly onMode: (mode: ReaderMode) => void;
  readonly onTurn: (index: number) => void;
}) {
  const iiif = useIiif();
  const frame = useRef<HTMLDivElement>(null);
  const controlsRef = useRef<ZoomControls | undefined>(undefined);
  const hintId = useId();
  const [zoomLevel, setZoomLevel] = useState<number | undefined>();
  const [failed, setFailed] = useState(false);
  const { full, fallback, toggle } = useFullscreen(frame);

  const count = pages.length;
  const playing = pages[current]?.media !== undefined ? pages[current] : undefined;
  // A stream plays alone, even in spread mode.
  const stageMode = playing !== undefined ? 'page' : mode;
  const visible = visiblePages(current, count, stageMode);
  const previous = turnTo(current, count, stageMode, -1);
  const next = turnTo(current, count, stageMode, 1);
  const images: StageImage[] = visible.flatMap((index) => {
    const page = pages[index];
    return page?.fileSetId === undefined || page.media !== undefined
      ? []
      : [{ info: iiif.info(page.fileSetId), width: page.width, height: page.height }];
  });
  const label = pageLabel(pages, visible, paged);
  const noun = nounOf(pages, paged);

  const turn = (target: number | undefined) => {
    if (target !== undefined) onTurn(target);
  };

  const onKeyDown = (event: KeyboardEvent<HTMLDivElement>) => {
    if (event.altKey || event.ctrlKey || event.metaKey) return;
    const zoom = controlsRef.current;
    const pans = count <= 1 || zoom?.zoomedIn() === true;
    switch (event.key) {
      case '+':
      case '=':
        zoom?.zoomBy(1.5);
        break;
      case '-':
      case '_':
        zoom?.zoomBy(1 / 1.5);
        break;
      case '0':
        zoom?.home();
        break;
      case 'r':
      case 'R':
        zoom?.rotate();
        break;
      case 'PageUp':
        turn(previous);
        break;
      case 'PageDown':
        turn(next);
        break;
      case 'Home':
        if (count > 1) onTurn(0);
        break;
      case 'End':
        if (count > 1) turn(visiblePages(count - 1, count, mode)[0]);
        break;
      case 'ArrowLeft':
        if (pans) zoom?.pan(-0.1, 0);
        else turn(previous);
        break;
      case 'ArrowRight':
        if (pans) zoom?.pan(0.1, 0);
        else turn(next);
        break;
      case 'ArrowUp':
        zoom?.pan(0, -0.1);
        break;
      case 'ArrowDown':
        zoom?.pan(0, 0.1);
        break;
      default:
        return;
    }
    event.preventDefault();
  };

  return (
    <div
      ref={frame}
      className={cn(
        'flex flex-col overflow-hidden bg-viewer font-sans text-viewer-foreground',
        full ? 'h-dvh' : 'rounded-xl ring-1 ring-border',
        fallback && 'fixed inset-0 z-50',
      )}
    >
      <div className="flex flex-wrap items-center gap-x-3 gap-y-1 border-b border-viewer-foreground/10 px-3 py-2">
        {count > 1 && (
          <div className="flex items-center gap-1">
            <Button
              variant="ghost"
              size="icon-sm"
              className={cn(TOOL, 'max-md:size-11')}
              aria-label={`Previous ${noun}`}
              disabled={previous === undefined}
              onClick={() => {
                turn(previous);
              }}
            >
              <ChevronLeftIcon aria-hidden="true" />
            </Button>
            <Button
              variant="ghost"
              size="icon-sm"
              className={cn(TOOL, 'max-md:size-11')}
              aria-label={`Next ${noun}`}
              disabled={next === undefined}
              onClick={() => {
                turn(next);
              }}
            >
              <ChevronRightIcon aria-hidden="true" />
            </Button>
          </div>
        )}
        <p
          aria-live="polite"
          className="min-w-0 flex-1 truncate text-sm font-medium"
          title={label ?? title}
        >
          {label ?? title}
        </p>
        <div className="ml-auto flex flex-wrap items-center gap-1">
          {paged && count > 2 && (
            <div
              role="group"
              aria-label="Layout"
              className="mr-1 flex rounded-md bg-viewer-foreground/10 p-0.5"
            >
              {(
                [
                  ['page', 'Page', <RectangleVerticalIcon key="page" aria-hidden="true" />],
                  ['spread', 'Spread', <Columns2Icon key="spread" aria-hidden="true" />],
                ] as const
              ).map(([value, text, icon]) => (
                <Button
                  key={value}
                  variant="ghost"
                  size="xs"
                  className={cn(TOOL, 'h-7 px-2')}
                  aria-pressed={mode === value}
                  onClick={() => {
                    onMode(value);
                  }}
                >
                  {icon}
                  {text}
                </Button>
              ))}
            </div>
          )}
          {playing === undefined && (
            <>
              <span className="min-w-12 rounded-md bg-viewer-foreground/10 px-2 py-1 text-center text-xs tabular-nums max-sm:hidden">
                <span className="sr-only">Zoom level </span>
                {zoomLevel === undefined ? '—' : `${String(zoomLevel)}%`}
              </span>
              <Tool
                name="Zoom out"
                onClick={() => {
                  controlsRef.current?.zoomBy(1 / 1.5);
                }}
              >
                <ZoomOutIcon aria-hidden="true" />
              </Tool>
              <Tool
                name="Zoom in"
                onClick={() => {
                  controlsRef.current?.zoomBy(1.5);
                }}
              >
                <ZoomInIcon aria-hidden="true" />
              </Tool>
              <Tool
                name="Fit to view"
                onClick={() => {
                  controlsRef.current?.home();
                }}
              >
                <MaximizeIcon aria-hidden="true" />
              </Tool>
              <Tool
                name="Rotate 90° clockwise"
                onClick={() => {
                  controlsRef.current?.rotate();
                }}
              >
                <RotateCwIcon aria-hidden="true" />
              </Tool>
            </>
          )}
          <Tool name={full ? 'Exit full screen' : 'Full screen'} onClick={toggle}>
            {full ? <ShrinkIcon aria-hidden="true" /> : <ExpandIcon aria-hidden="true" />}
          </Tool>
        </div>
      </div>
      {playing?.media !== undefined ? (
        <div
          role="region"
          aria-label={`Player: ${title}`}
          className={cn(
            'relative w-full',
            full ? 'min-h-0 flex-1' : 'h-[min(66vh,600px)] min-h-80',
          )}
        >
          <Suspense fallback={<StageLoading />}>
            <MediaStage
              media={playing.media}
              poster={
                playing.fileSetId !== undefined ? iiif.image(playing.fileSetId, 1600) : undefined
              }
              title={playing.label === title || count <= 1 ? title : `${title}, ${playing.label}`}
              onFailed={setFailed}
            />
          </Suspense>
          {failed && (
            <StageMessage
              alert
              title="This recording could not be played."
              detail="Try again in a minute, or in another browser."
            />
          )}
        </div>
      ) : (
        <div
          role="application"
          aria-label={`Zoomable image: ${title}`}
          aria-describedby={hintId}
          tabIndex={0}
          onKeyDown={onKeyDown}
          className={cn(
            'relative w-full outline-none focus-visible:ring-3 focus-visible:ring-ring/60 focus-visible:ring-inset',
            full ? 'min-h-0 flex-1' : 'h-[min(66vh,600px)] min-h-80',
          )}
        >
          <span id={hintId} className="sr-only">
            {KEYS_HINT}
            {count > 1 ? ` ${TURN_HINT}` : ''}
          </span>
          {images.length > 0 ? (
            <Suspense fallback={<StageLoading />}>
              <DeepZoom
                images={images}
                controlsRef={controlsRef}
                onZoom={setZoomLevel}
                onFailed={setFailed}
              />
            </Suspense>
          ) : (
            <StageMessage title="This item has no image to show." />
          )}
          {failed && (
            <StageMessage
              alert
              title="The image service could not open this image."
              detail="Try again in a minute, or download the image instead."
            />
          )}
        </div>
      )}
      {count > 1 && <PageStrip pages={pages} visible={visible} noun={noun} onTurn={onTurn} />}
    </div>
  );
}

/** A labelled icon button in the stage's toolbar. */
function Tool({
  name,
  onClick,
  children,
}: {
  readonly name: string;
  readonly onClick: () => void;
  readonly children: ReactNode;
}) {
  return (
    <Button
      variant="ghost"
      size="icon-sm"
      className={cn(TOOL, 'bg-viewer-foreground/5')}
      aria-label={name}
      onClick={onClick}
    >
      {children}
    </Button>
  );
}

export const KEYS_HINT = 'Plus and minus zoom, arrow keys pan, 0 fits the image, R rotates it.';
const TURN_HINT =
  'Page Up and Page Down turn the pages; so do the left and right arrows while the image is not zoomed in.';

function StageLoading() {
  return (
    <span className="absolute inset-0 grid place-items-center">
      <LoaderCircleIcon
        aria-hidden="true"
        className="size-6 animate-spin text-viewer-foreground/60 motion-reduce:animate-none"
      />
    </span>
  );
}

function StageMessage({
  title,
  detail,
  alert = false,
}: {
  readonly title: string;
  readonly detail?: string;
  readonly alert?: boolean;
}) {
  return (
    <div
      role={alert ? 'alert' : undefined}
      className="absolute inset-0 grid place-content-center justify-items-center gap-2 bg-viewer p-6 text-center"
    >
      <ImageOffIcon aria-hidden="true" className="size-6 text-viewer-foreground/70" />
      <p className="text-sm font-medium">{title}</p>
      {detail !== undefined && <p className="text-[13px] text-viewer-foreground/70">{detail}</p>}
    </div>
  );
}

/** The thumbnails under the stage: one button per page, the pages on the stage marked current. */
function PageStrip({
  pages,
  visible,
  noun,
  onTurn,
}: {
  readonly pages: readonly Page[];
  readonly visible: readonly number[];
  readonly noun: 'page' | 'image' | 'item';
  readonly onTurn: (index: number) => void;
}) {
  const list = useRef<HTMLOListElement>(null);
  const first = visible[0];
  useEffect(() => {
    // Scrolls the strip only: scrollIntoView would scroll the page to the strip as well.
    const strip = list.current;
    const button = strip?.querySelector('[aria-current="true"]');
    if (strip === null || button === null || button === undefined) return;
    const shown = strip.getBoundingClientRect();
    const thumb = button.getBoundingClientRect();
    if (thumb.left >= shown.left && thumb.right <= shown.right) return;
    strip.scrollLeft += thumb.left - shown.left - (shown.width - thumb.width) / 2;
  }, [first]);
  return (
    <nav aria-label={`${capitalized(noun)}s`} className="border-t border-viewer-foreground/10">
      <ol ref={list} className="flex gap-2 overflow-x-auto px-3 py-3">
        {pages.map((page) => {
          const shown = visible.includes(page.index);
          return (
            <li key={page.index} className="shrink-0">
              <button
                type="button"
                aria-current={shown ? 'true' : undefined}
                onClick={() => {
                  onTurn(page.index);
                }}
                className={cn(
                  'group relative grid w-16 gap-1 rounded-md p-0.5 text-left outline-none focus-visible:ring-3 focus-visible:ring-ring/60',
                  shown ? 'text-viewer-foreground' : 'text-viewer-foreground/65',
                )}
              >
                <span className="relative">
                  {page.media?.kind === 'sound' && page.fileSetId === undefined ? (
                    <span
                      className={cn(
                        'grid h-20 w-full place-items-center rounded-sm bg-viewer-foreground/10 ring-1',
                        shown
                          ? 'ring-2 ring-viewer-foreground'
                          : 'ring-viewer-foreground/15 group-hover:ring-viewer-foreground/50',
                      )}
                    >
                      <AudioLinesIcon aria-hidden="true" className="size-6" />
                    </span>
                  ) : (
                    <IiifImage
                      fileSetId={page.fileSetId}
                      size={160}
                      className={cn(
                        'h-20 w-full rounded-sm bg-viewer-foreground/10 ring-1',
                        shown
                          ? 'ring-2 ring-viewer-foreground'
                          : 'ring-viewer-foreground/15 group-hover:ring-viewer-foreground/50',
                      )}
                    />
                  )}
                  {page.media !== undefined && (
                    <span className="absolute right-1 bottom-1 rounded-sm bg-black/75 px-1 text-[10px] leading-4 text-white tabular-nums">
                      <span className="sr-only">Running time </span>
                      {clockTime(page.media.durationMs)}
                    </span>
                  )}
                </span>
                <span className="truncate text-[11px] leading-tight">
                  <span className="sr-only">{`${capitalized(noun)} ${String(page.index + 1)}:`}</span>{' '}
                  {page.label}
                </span>
              </button>
            </li>
          );
        })}
      </ol>
    </nav>
  );
}
