import { useMemo, useState } from 'react';
import { Link, useSearchParams } from 'react-router';
import type { CollectionRef, IiifManifest, PublicWork } from '../../api/client.js';
import { useIiif } from '../../api/iiif.js';
import { useCollections, useSearch } from '../../api/queries.js';
import { Container, PageTitle, SectionHeading } from '../../components/layout.js';
import { TextLink } from '../../components/links.js';
import { WorkCard, workTitle } from '../../components/WorkCard.js';
import { readableEdtf, yearsLabel } from '../../lib/dates.js';
import {
  bylineNames,
  catalogDate,
  filterHref,
  isPaged,
  mapValues,
  metadataRows,
  pageFromParam,
  pagesOf,
  pdfsOf,
  rightsOf,
  visiblePages,
  type MetadataRow,
  type ReaderMode,
} from './manifest.js';
import { Reader } from './Reader.js';
import { WorkActions } from './WorkActions.js';
import { ContentsCard, IiifCard, PartOfCard, RightsCard } from './WorkCards.js';
import {
  Breadcrumb,
  BreadcrumbItem,
  BreadcrumbLink,
  BreadcrumbList,
  BreadcrumbPage,
  BreadcrumbSeparator,
} from '@/components/ui/breadcrumb';

/** Record rows whose values are EDTF dates, shown as a reader says them (`1938~` → about 1938). */
const DATE_ROWS = new Set(['Date created', 'Date issued']);

function Record({ rows }: { readonly rows: readonly MetadataRow[] }) {
  return (
    <dl className="divide-y divide-border border-y border-border text-sm">
      {rows.map((row) => (
        <div
          key={row.label}
          className="grid gap-1 py-2.5 sm:grid-cols-[minmax(8rem,11rem)_minmax(0,1fr)] sm:gap-4"
        >
          <dt className="text-muted-foreground">{row.label}</dt>
          <dd className="grid gap-1 break-words">
            {row.values.map((value, index) => (
              <span key={index}>
                {value.filter !== undefined ? (
                  <TextLink to={filterHref(value.filter)}>{value.text}</TextLink>
                ) : DATE_ROWS.has(row.label) ? (
                  readableEdtf(value.text)
                ) : (
                  value.text
                )}
              </span>
            ))}
          </dd>
        </div>
      ))}
    </dl>
  );
}

/** "More from <collection>": other works of the work's first collection. */
function MoreFromCollection({
  collection,
  workId,
}: {
  readonly collection: CollectionRef;
  readonly workId: string;
}) {
  const search = useSearch({ filters: { collection: [collection.id] }, limit: 6, facetLimit: 1 });
  const others = (search.data?.items ?? []).filter((hit) => hit.id !== workId).slice(0, 5);
  if (others.length === 0) return null;
  return (
    <section aria-labelledby="more-from" className="pt-12">
      <SectionHeading
        id="more-from"
        link={{ text: 'View collection', to: `/collections/${collection.slug}` }}
      >
        {`More from ${collection.title}`}
      </SectionHeading>
      <div className="mt-5 grid grid-cols-2 gap-x-5 gap-y-7 sm:grid-cols-3 lg:grid-cols-5">
        {others.map((hit) => (
          <WorkCard key={hit.id} work={hit} aspect="aspect-[3/4]" />
        ))}
      </div>
    </section>
  );
}

/** Books open as spreads on wide screens, one page at a time on phones. */
const wideScreen = () => window.matchMedia('(min-width: 1024px)').matches;

/**
 * The work page once its record and manifest are in: loaded lazily with the reader, the actions
 * and the citations, so the site's first page does not carry them.
 */
export default function WorkDetail({
  work,
  manifest,
}: {
  readonly work: PublicWork;
  readonly manifest: IiifManifest;
}) {
  const iiif = useIiif();
  const collections = useCollections();
  const [params, setParams] = useSearchParams();
  const pages = useMemo(() => pagesOf(manifest), [manifest]);
  const paged = isPaged(manifest);
  const [mode, setMode] = useState<ReaderMode>(() =>
    paged && pages.length > 2 && wideScreen() ? 'spread' : 'page',
  );
  const current = pageFromParam(params.get('page'), pages.length);
  const visible = visiblePages(current, pages.length, mode);
  const turn = (index: number) => {
    setParams(
      (previous) => {
        const next = new URLSearchParams(previous);
        if (index === 0) next.delete('page');
        else next.set('page', String(index + 1));
        return next;
      },
      { replace: true, preventScrollReset: true },
    );
  };

  const title = workTitle(work);
  const rights = rightsOf(manifest);
  const rows = metadataRows(manifest, work);
  const names = bylineNames(manifest, work);
  const edtf = catalogDate(work.mods);
  const date = edtf !== undefined ? readableEdtf(edtf) : yearsLabel(work.yearStart, work.yearEnd);
  const summary = mapValues(manifest.summary);
  const manifestUrl = iiif.manifest(work.id);
  const workUrl = `${window.location.origin}/works/${work.id}`;
  const collection = work.collections[0];
  const facts = [...names, date].filter((fact) => fact !== undefined && fact !== '');

  return (
    <Container className="pt-5 pb-12 md:pt-6">
      <Breadcrumb>
        <BreadcrumbList>
          <BreadcrumbItem>
            <BreadcrumbLink render={<Link to="/collections" />}>Collections</BreadcrumbLink>
          </BreadcrumbItem>
          {collection !== undefined && (
            <>
              <BreadcrumbSeparator />
              <BreadcrumbItem>
                <BreadcrumbLink render={<Link to={`/collections/${collection.slug}`} />}>
                  {collection.title}
                </BreadcrumbLink>
              </BreadcrumbItem>
            </>
          )}
          <BreadcrumbSeparator />
          <BreadcrumbItem className="min-w-0">
            <BreadcrumbPage className="truncate">{title}</BreadcrumbPage>
          </BreadcrumbItem>
        </BreadcrumbList>
      </Breadcrumb>

      <div className="mt-4 max-md:-mx-4">
        <Reader
          title={title}
          pages={pages}
          paged={paged}
          current={current}
          mode={mode}
          onMode={setMode}
          onTurn={turn}
        />
      </div>

      <div className="grid gap-8 pt-8 lg:grid-cols-[minmax(0,1fr)_340px] lg:gap-10">
        <div className="min-w-0">
          <PageTitle>{title}</PageTitle>
          {(facts.length > 0 || work.collections.length > 0) && (
            <p className="mt-2 text-[15px] text-muted-foreground">
              {facts.join(' · ')}
              {work.collections.map((item, index) => (
                <span key={item.id}>
                  {index > 0 || facts.length > 0 ? ' · ' : ''}
                  <TextLink to={`/collections/${item.slug}`}>{item.title}</TextLink>
                </span>
              ))}
            </p>
          )}
          <div className="mt-5">
            <WorkActions
              work={work}
              page={pages[current]}
              pageCount={pages.length}
              pdfs={pdfsOf(manifest)}
              manifestUrl={manifestUrl}
              workUrl={workUrl}
              rights={rights.name}
            />
          </div>
          {summary.map((paragraph) => (
            <p
              key={paragraph}
              className="mt-6 max-w-2xl font-heading text-lg leading-relaxed text-foreground"
            >
              {paragraph}
            </p>
          ))}
          <h2 className="mt-8 mb-2 font-heading text-lg font-semibold">About this item</h2>
          <Record rows={rows} />
        </div>
        <aside
          aria-label="About the item"
          className="grid grid-cols-[minmax(0,1fr)] content-start gap-4"
        >
          <RightsCard rights={rights} />
          {paged && pages.length > 1 && (
            <ContentsCard pages={pages} visible={visible} onTurn={turn} />
          )}
          <PartOfCard
            collections={work.collections}
            details={collections.data}
            fallbackFileSetId={work.representativeFileSetId}
          />
          <IiifCard manifestUrl={manifestUrl} />
        </aside>
      </div>

      {collection !== undefined && <MoreFromCollection collection={collection} workId={work.id} />}
    </Container>
  );
}
