import { ExternalLinkIcon, ScaleIcon } from 'lucide-react';
import type { ReactNode } from 'react';
import { Link } from 'react-router';
import type { CollectionRef, PublicCollection } from '../../api/client.js';
import { IiifImage } from '../../components/IiifImage.js';
import { TEXT_LINK } from '../../components/links.js';
import type { Page, Rights } from './manifest.js';
import { CopyButton, IIIF_VIEWERS } from './WorkActions.js';
import { cn } from '@/lib/utils';

/** The work page's side cards: rights, the collections it is part of, IIIF and a book's contents. */

function SideCard({
  heading,
  children,
  className,
}: {
  readonly heading: string;
  readonly children: ReactNode;
  readonly className?: string;
}) {
  return (
    <section
      aria-label={heading}
      className={cn('rounded-xl border border-border bg-card p-4 shadow-xs', className)}
    >
      <h2 className="text-xs font-semibold tracking-wider text-muted-foreground uppercase">
        {heading}
      </h2>
      {children}
    </section>
  );
}

/** `rightsstatements.org` for the link under the statement. */
const hostOf = (href: string) => {
  try {
    return new URL(href).hostname.replace(/^www\./, '');
  } catch {
    return href;
  }
};

export function RightsCard({ rights }: { readonly rights: Rights }) {
  if (rights.name === undefined && rights.statement === undefined && rights.href === undefined) {
    return null;
  }
  return (
    <SideCard heading="Rights">
      <div className="mt-2 flex gap-3">
        <span className="grid size-8 shrink-0 place-items-center rounded-full bg-success/10 text-success">
          <ScaleIcon aria-hidden="true" className="size-4" />
        </span>
        <div className="min-w-0 text-sm">
          {rights.name !== undefined && <p className="font-medium">{rights.name}</p>}
          {rights.statement !== undefined && (
            <p className="mt-0.5 text-muted-foreground">{rights.statement}</p>
          )}
          {rights.href !== undefined && (
            <a
              href={rights.href}
              target="_blank"
              rel="noreferrer"
              className={cn(TEXT_LINK, 'mt-1.5 inline-flex items-center gap-1 text-[13px]')}
            >
              {hostOf(rights.href)}
              <ExternalLinkIcon aria-hidden="true" className="size-3.5" />
              <span className="sr-only"> (the rights statement, opens in a new tab)</span>
            </a>
          )}
        </div>
      </div>
    </SideCard>
  );
}

export function PartOfCard({
  collections,
  details,
  fallbackFileSetId,
}: {
  readonly collections: readonly CollectionRef[];
  /** Every published collection, for work counts and thumbnails; undefined while loading. */
  readonly details: readonly PublicCollection[] | undefined;
  /** The work's own image, for a collection the API sends no thumbnail for. */
  readonly fallbackFileSetId: string | null;
}) {
  if (collections.length === 0) return null;
  return (
    <SideCard heading="Part of">
      <ul className="mt-2 grid gap-2">
        {collections.map((collection) => {
          const detail = details?.find((item) => item.id === collection.id);
          return (
            <li key={collection.id}>
              <Link
                to={`/collections/${collection.slug}`}
                className="group flex items-center gap-3 rounded-lg focus-visible:ring-3 focus-visible:ring-ring/50 focus-visible:outline-none"
              >
                <IiifImage
                  fileSetId={detail?.thumbnailFileSetIds?.[0] ?? fallbackFileSetId}
                  size={160}
                  className="size-14 shrink-0 rounded-md ring-1 ring-border"
                />
                <span className="min-w-0">
                  <span className="block font-heading leading-snug font-semibold decoration-border underline-offset-4 group-hover:underline">
                    {collection.title}
                  </span>
                  {detail !== undefined && (
                    <span className="text-[13px] text-muted-foreground">
                      {detail.workCount === 1 ? '1 work' : `${String(detail.workCount)} works`}
                    </span>
                  )}
                </span>
              </Link>
            </li>
          );
        })}
      </ul>
    </SideCard>
  );
}

export function IiifCard({ manifestUrl }: { readonly manifestUrl: string }) {
  return (
    <SideCard heading="IIIF">
      <p className="mt-1 text-sm text-muted-foreground">Open this item in any IIIF viewer.</p>
      <div className="mt-2 flex items-center gap-1 rounded-md border border-input bg-secondary py-0.5 pr-0.5 pl-2.5">
        <span
          className="min-w-0 flex-1 truncate font-mono text-[11px] text-muted-foreground"
          title={manifestUrl}
        >
          {manifestUrl}
        </span>
        <CopyButton text={manifestUrl} what="Manifest URL" />
      </div>
      <ul className="mt-2 flex flex-wrap gap-x-3 gap-y-1 text-[13px] font-medium">
        {IIIF_VIEWERS.map((viewer) => (
          <li key={viewer.name}>
            <a
              href={viewer.href(manifestUrl)}
              target="_blank"
              rel="noreferrer"
              className={cn(TEXT_LINK, 'inline-flex items-center gap-1')}
            >
              {viewer.name}
              <ExternalLinkIcon aria-hidden="true" className="size-3" />
              <span className="sr-only"> (opens in a new tab)</span>
            </a>
          </li>
        ))}
      </ul>
    </SideCard>
  );
}

/** A book's pages as a list; the pages on the stage are marked. */
export function ContentsCard({
  pages,
  visible,
  onTurn,
}: {
  readonly pages: readonly Page[];
  readonly visible: readonly number[];
  readonly onTurn: (index: number) => void;
}) {
  return (
    <SideCard heading="Contents">
      <ol className="mt-2 grid max-h-96 gap-0.5 overflow-y-auto text-sm">
        {pages.map((page) => {
          const shown = visible.includes(page.index);
          return (
            <li key={page.index}>
              <button
                type="button"
                aria-current={shown ? 'true' : undefined}
                onClick={() => {
                  onTurn(page.index);
                }}
                className={cn(
                  'relative flex w-full justify-between gap-3 rounded-md px-2 py-1 text-left outline-none hover:bg-secondary focus-visible:ring-3 focus-visible:ring-ring/50',
                  shown && 'bg-secondary font-medium',
                )}
              >
                <span className="truncate">{page.label}</span>
                <span className="text-muted-foreground tabular-nums">
                  <span className="sr-only">page </span>
                  {page.index + 1}
                </span>
              </button>
            </li>
          );
        })}
      </ol>
    </SideCard>
  );
}
